function isVideoUrl(url) {
    const pathname = url.split(/[?#]/, 1)[0];
    return /\.(mp4|webm|mov|avi|mkv)$/i.test(pathname);
}
function splitMediaUrls(urls) {
    return urls.reduce((acc, url) => {
        if (!url)
            return acc;
        if (isVideoUrl(url)) {
            acc.videos.push(url);
        }
        else {
            acc.images.push(url);
        }
        return acc;
    }, { images: [], videos: [] });
}
